import os,sys,pathlib,json,signal,selectors
log=pathlib.Path(sys.argv[1]);ack=pathlib.Path(sys.argv[2]);sequence=0;generation=0;reopen_requested=False
stream=os.fdopen(os.open(log,os.O_WRONLY|os.O_CREAT|os.O_APPEND,0o600),'ab',buffering=0)
def acknowledge(previous=None):
 value={'pid':os.getpid(),'inode':os.fstat(stream.fileno()).st_ino,'generation':generation,'previous_inode':previous}
 ack.write_text(json.dumps(value));return value
def request_reopen(signum,frame):
 global reopen_requested
 reopen_requested=True
signal.signal(signal.SIGUSR1,request_reopen)
print(json.dumps({'event':'ready',**acknowledge()}),flush=True)
selector=selectors.DefaultSelector();selector.register(sys.stdin,selectors.EVENT_READ)
try:
 while True:
  if reopen_requested:
   previous=os.fstat(stream.fileno()).st_ino;stream.close();stream=os.fdopen(os.open(log,os.O_WRONLY|os.O_APPEND),'ab',buffering=0);generation+=1;reopen_requested=False;acknowledge(previous)
  if not selector.select(.03):continue
  line=sys.stdin.readline()
  if not line:break
  parts=line.split()
  if parts==['QUIT']:break
  if parts and parts[0]=='WRITE':
   for _ in range(int(parts[1])):
    sequence+=1;stream.write((f'{sequence:05d}|'+('X'*96)+'\n').encode())
   os.fsync(stream.fileno());print(json.dumps({'event':'written','last_sequence':sequence,'inode':os.fstat(stream.fileno()).st_ino}),flush=True)
  elif parts==['INFO']:print(json.dumps({'event':'info','last_sequence':sequence,'inode':os.fstat(stream.fileno()).st_ino,'generation':generation}),flush=True)
  else:raise ValueError('unknown fixture instruction')
finally:stream.close();selector.close()

