        assert len(raw)==value['bytes']and hashlib.sha256(raw).hexdigest()==value['sha256'],'retained original file seal'
        if name.startswith('job-')and name.endswith('.end.json'):rows.append(json.loads(raw))
    rows.sort(key=lambda row:row['started_ns']);rotated=[];empty=[]
    for row in rows:
        assert row['uid']==row['gid']==1000 and row['ended_ns']>row['started_ns']and row['returncode']==0
        assert '--force'not in row['command']and '-f'not in row['command']and row['actual_parent_chain'][-1]['pid']==native['scheduler_command']['pid']
        ack=[]
        for side in ('before','after'):
            for value in row[side].values():
                raw=base64.b64decode(value['raw_base64'],validate=True);assert len(raw)==value['bytes']and hashlib.sha256(raw).hexdigest()==value['sha256']
            ack.append(json.loads(base64.b64decode(row[side]['writer.ack.json']['raw_base64'])))
        if ack[1]['generation']>ack[0]['generation']:
            assert ack[1]['generation']==ack[0]['generation']+1 and ack[1]['previous_inode']==ack[0]['inode']and ack[1]['inode']!=ack[0]['inode'];rotated.append(row)
        elif row['before']['application log.log']['bytes']==0:empty.append(row)
    assert len(rotated)==3 and empty and len(rows)>=4
    original_chunks=[]
    for observation in native['observations']:
        value=observation['actual_newest_archive'];raw=base64.b64decode(value['base64'],validate=True)
        assert len(raw)==value['bytes']and hashlib.sha256(raw).hexdigest()==value['sha256']
        decoded=gzip.decompress(raw)if value['name'].endswith('.gz')else raw
        assert len(decoded)==value['decoded_bytes']and hashlib.sha256(decoded).hexdigest()==value['decoded_sha256'];original_chunks.append(decoded)
    original_chunks.append(base64.b64decode(files['application log.log']['base64']))
    assert original_chunks==[base64.b64decode(s)for s in native['continuity_chunks_base64']]
    numbers=[]
    for chunk in original_chunks:
        for line in chunk.splitlines():numbers.append(int(line[:5]))
    assert numbers==list(range(1,41))and all(value['reaped']for value in native['callback_cleanup'])
    lines=base64.b64decode(files['scheduler.log']['base64']).decode().splitlines();next_messages=[]
    for line in lines:
        found=re.search('msg="job will run next at (.*?)"',line)
        if found:next_messages.append(found[1])
    assert next_messages
    sizes=[value for name,value in files.items()if name=='application log.log'or re.fullmatch('application log[.]log[.][0-9]+(?:[.]gz)?',name)]
    return {'manual_rotations':len(record['manual']['history']),'scheduled_invocations':len(rows),'scheduled_successes':len(rows),'scheduled_rotations':len(rotated),'scheduled_empty_checks':len(empty),'actual_start_wall_ns':[row['started_wall_ns']for row in rows],'actual_intervals_ns':[rows[i]['started_ns']-rows[i-1]['started_ns']for i in range(1,len(rows))],'next_calculated_before_stop':next_messages[-1],'sequence_numbers':numbers,'retained_logical_bytes':sum(v['bytes']for v in sizes),'retained_allocated_bytes':sum(v['allocated_bytes']for v in sizes),'scheduler_reaped':native['scheduler_cleanup']['reaped']}
